  pros = ARRAY['Нативна інтеграція у VS Code і JetBrains', 'Copilot Chat для запитань про код', 'Підтримка всіх основних мов', 'Безкоштовний тариф доступний'],
  cons = ARRAY['Перехід на оплату за використання з червня 2026', 'Може пропонувати код з вразливостями', 'Потребує інтернет-зʼєднання']
WHERE slug = 'github-copilot' AND lang = 'ua';

